 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, color))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            pieces.append(cells)

    # Slide each rigid object rightward; settle rightmost objects first.
    pieces.sort(key=lambda p: max(c for _, c, _ in p), reverse=True)
    out = [[0] * w for _ in range(h)]
    for piece in pieces:
        shift = 0
        while True:
            candidate = [(r, c + shift + 1) for r, c, _ in piece]
            if any(c >= w or out[r][c] != 0 for r, c in candidate):
                break
            shift += 1
        for r, c, color in piece:
            out[r][c + shift] = color
    return out
